package com.growworld.repository; import com.growworld.domain.*; import java.time.LocalDate; import java.util.*; import org.springframework.data.domain.*; import org.springframework.data.jpa.repository.*;
public interface ActivityRecordRepository extends JpaRepository<ActivityRecord,UUID>{ @Query("select coalesce(sum(a.expAwarded),0) from ActivityRecord a where a.user.id=:userId") int totalExp(UUID userId); long countDistinctByUserId(UUID userId); List<ActivityRecord> findByUserIdAndPerformedOnOrderByCreatedAtDesc(UUID userId,LocalDate date); Page<ActivityRecord> findByUserIdOrderByCreatedAtDesc(UUID userId, Pageable pageable); }
